SELECT p.id AS position_id, CASE WHEN s.id=p.signal_id THEN 'ENTRY' ELSE 'EXIT' END AS role, s.id, s.symbol, s.interval_code, s.candle_open_time, s.generated_at, s.created_at, s.decision, s.original_decision, s.total_score, s.confidence_score, s.final_entry_allowed, s.latest_price, s.stop_loss, s.take_profit, s.risk_reward_ratio, s.atr_percent, s.volatility_level, s.atr_entry_type, s.market_regime, s.market_regime_confidence, s.selected_strategy, s.strategy_entry_allowed, s.confluence_status, s.confluence_entry_allowed, s.btc_context_status, s.btc_context_entry_allowed, s.liquidity_status, s.derivatives_status, LEFT(s.final_decision_explanation,500) AS final_expl FROM paper_position p JOIN trade_signal s ON s.id IN (p.signal_id, p.exit_signal_id) WHERE p.id IN (182,172,162,158,143,137) ORDER BY p.id, role